/** @vitest-environment node */
// Port of the prompt tests in backend/tests/unit/test_ai_prompt.py, plus byte-for-byte equality
// with the Python prompt builders (fixture generated by __fixtures__/generate.py).
import { describe, expect, it } from "vitest";
import golden from "./__fixtures__/python-golden.json";
import type { ClipLength } from "./clip-duration";
import {
  buildCandidateRerankPrompt,
  buildTranscriptAnalysisPrompt,
  buildTranscriptSystemPrompt,
  CANDIDATE_RERANK_SYSTEM_PROMPT,
} from "./prompts";
import { CANDIDATE_RANKING_SCHEMA, parseTranscriptAnalysis, TRANSCRIPT_ANALYSIS_SCHEMA } from "./schemas";

describe("prompts match the Python builders", () => {
  it.each(Object.entries(golden.prompts.system))("system prompt for %s", (preset, expected) => {
    expect(buildTranscriptSystemPrompt(preset as ClipLength)).toBe(expected);
  });

  it("rerank system prompt", () => {
    expect(CANDIDATE_RERANK_SYSTEM_PROMPT).toBe(golden.prompts.rerank_system);
  });

  it.each(golden.prompts.analysis.map((c, i) => [i, c] as const))("analysis prompt case %i", (_, c) => {
    expect(
      buildTranscriptAnalysisPrompt({
        transcript: c.transcript,
        clipSignals: c.clip_signals,
        window: c.window as [number, number] | null,
        clipLength: c.clip_length as ClipLength,
      }),
    ).toBe(c.prompt);
  });

  it("rerank prompt", () => {
    const { most_relevant_segments: candidates } = parseTranscriptAnalysis({
      most_relevant_segments: golden.prompts.rerank.candidates,
      summary: "",
      key_topics: [],
    });
    expect(buildCandidateRerankPrompt(candidates)).toBe(golden.prompts.rerank.prompt);
  });

  it("output schemas", () => {
    const sent = golden.requests["claude-opus-5"];
    expect(TRANSCRIPT_ANALYSIS_SCHEMA).toEqual(sent.analysis.output_config.format.schema);
    expect(CANDIDATE_RANKING_SCHEMA).toEqual(sent.ranking.output_config.format.schema);
  });
});

describe("prompt content", () => {
  it("system prompt enforces the grounding rules", () => {
    const prompt = buildTranscriptSystemPrompt();
    for (const phrase of [
      "extraction and ranking, not creative rewriting",
      "Never invent facts, tone, context, or transitions",
      "Each selected segment must map to one contiguous range",
      "Do not judge, moralize, or downgrade a segment",
      "25-50 seconds",
      "Bad picks include intros",
      "The clip's real first sentence is the hook",
      "bare agreement",
      "Return valid JSON only",
      'Do not use "segment" as an output field. Use "text".',
    ]) {
      expect(prompt).toContain(phrase);
    }
  });

  it("analysis prompt requires transcript fidelity", () => {
    const prompt = buildTranscriptAnalysisPrompt({ transcript: "[00:12 - 00:21] A strong opening line" });
    for (const phrase of [
      "Do not fabricate or embellish content.",
      "Do not merge separate non-contiguous moments into one segment.",
      'If there is a tradeoff between "viral" and "accurate", choose accuracy.',
      "Do not reject or penalize a segment simply because of the subject matter",
      "Most selected clips should be 25-50 seconds.",
      "viewer would understand and care without seeing the rest",
      "first word of a self-contained sentence",
      "Return one valid JSON object and nothing else.",
      "No Markdown, headings, bullets, code fences",
      "[00:12 - 00:21] A strong opening line",
    ]) {
      expect(prompt).toContain(phrase);
    }
  });

  it("adds the channel notes to the analysis and rerank prompts only when given", () => {
    const transcript = "[00:12 - 00:21] A strong opening line";
    const notes = "- 12 recent posted Shorts, median 900 views.";
    const plain = buildTranscriptAnalysisPrompt({ transcript });
    const withNotes = buildTranscriptAnalysisPrompt({ transcript, channelNotes: notes });
    expect(plain).not.toContain("creator's channel");
    expect(withNotes).toContain(notes);
    expect(withNotes).toContain("soft preference");
    // The transcript stays last, after the notes.
    expect(withNotes.endsWith(transcript)).toBe(true);
    expect(buildCandidateRerankPrompt([], notes)).toContain(notes);
    expect(buildCandidateRerankPrompt([])).not.toContain("creator's channel");
  });

  it("never asks for B-roll or performance history", () => {
    const prompt = buildTranscriptAnalysisPrompt({ transcript: "[00:12 - 00:21] A strong opening line" }).toLowerCase();
    expect(prompt).not.toContain("b-roll");
    expect(prompt).not.toContain("broll");
    expect(prompt).not.toContain("performance history");
    expect(buildTranscriptSystemPrompt("auto").toLowerCase()).not.toContain("b-roll");
  });
});
